-- 2. Every other library character keeps its English name in Spanish.
insert into public.character_names (character_id, lang, name, norm, aliases, alias_norms)
select n.character_id, 'es', n.name, n.norm, '{}', '{}'
from public.character_names n
join public.characters c on c.id = n.character_id
where n.lang = 'en' and c.created_by is null
on conflict (character_id, lang) do nothing;

-- 3. Spanish names given earlier that the agents corrected (the old one stays an
-- alias), and Spanish aliases for them.
update public.character_names n
set
  name = coalesce(v.name, n.name),
  norm = coalesce(v.norm, n.norm),
  aliases = array(
    select a from unnest(n.aliases || v.aliases) with ordinality u(a, i)
    where a <> coalesce(v.name, n.name)
    group by a order by min(i)
  ),
  alias_norms = array(
    select a from unnest(n.alias_norms || v.alias_norms) with ordinality u(a, i)
    where a <> coalesce(v.norm, n.norm)
    group by a order by min(i)
  )
from (values
