) as v(id, old_name, name, norm, aliases, alias_norms)
where n.character_id = v.id and n.lang = 'es'
  and (v.old_name is null or n.name = v.old_name);

-- 4. Each Spanish name joins the other languages' normalised aliases, and theirs
-- the Spanish one's, as the library's own rows have them.
update public.character_names n
set alias_norms = array(
  select distinct x from (
    select unnest(n.alias_norms) as x
    union select o.norm from public.character_names o
    where o.character_id = n.character_id and o.lang <> n.lang
  ) s where x <> n.norm
)
where n.lang = 'es' and n.character_id not like 'u-%';
update public.character_names n
set alias_norms = n.alias_norms || e.norm
from public.character_names e
where e.character_id = n.character_id and e.lang = 'es' and n.lang <> 'es'
  and e.norm <> n.norm and not (e.norm = any(n.alias_norms));

