),
scored as (
  select t.id, 22000 + coalesce((
    select least(1500, greatest(-1500, round(max(o.popularity - case o.lang
      when 'en' then 29968 when 'pt' then 20940 else 23555 end) / 3.0)))::integer
    from public.character_names o
    where o.character_id = t.id and o.lang in ('en', 'ja', 'pt') and o.popularity is not null
  ), 0) as p
  from t
),
joining as (
  select distinct on (n.norm, c.category) s.id, s.p
  from scored s
  join public.character_names n on n.character_id = s.id and n.lang = 'es'
  join public.characters c on c.id = s.id
  where n.popularity is null
    and not exists (
      select 1 from public.character_names v
      join public.characters vc on vc.id = v.character_id
      where v.lang = 'es' and v.norm = n.norm and v.popularity is not null
        and v.character_id <> s.id and vc.category is not distinct from c.category
    )
  order by n.norm, c.category, s.p desc, s.id
)
update public.character_names n
set popularity = j.p
from joining j
where n.character_id = j.id and n.lang = 'es' and n.popularity is null;

